require_once __DIR__.'/../includes/bootstrap.php';$id=(int)($_GET['id']??0);$r=db_one('SELECT r.*,p.ppmp_no,d.department_name FROM procurement_requests r JOIN procurement_ppmp p ON p.id=r.ppmp_id LEFT JOIN departments d ON d.id=r.department_id WHERE r.id=?',[$id]);if(!$r)exit('Purchase Request not found.');$items=db_all('SELECT * FROM procurement_request_items WHERE request_id=? ORDER BY id',[$id]);
?><!doctype html><html><head><meta charset="utf-8"><title><?=e($r['pr_no'])?></title><style>@page{size:A4 portrait;margin:16mm}*{box-sizing:border-box}body{margin:0;color:#000;font:10px "Times New Roman",serif}.toolbar{position:fixed;top:8px;right:8px}.toolbar button,.toolbar a{padding:8px 12px;margin-left:5px}.sheet{width:100%}.title{text-align:center;font-weight:bold;font-size:14px;margin:18px 0 28px}.entity{display:flex;justify-content:space-between;font-weight:bold}.meta{width:100%;border-collapse:collapse}.meta td{border:1px solid #000;padding:5px}.items{width:100%;border-collapse:collapse;table-layout:fixed}.items th,.items td{border:1px solid #000;padding:4px;vertical-align:top}.items th{text-align:center}.center{text-align:center}.num{text-align:right}.purpose{border:1px solid #000;border-top:0;padding:7px}.sign{display:grid;grid-template-columns:1fr 1fr;border:1px solid #000;border-top:0;min-height:100px}.sign>div{padding:8px;text-align:center}.sign strong{display:block;margin-top:38px}.page{break-inside:avoid}@media print{.toolbar{display:none}}</style><link rel="stylesheet" href="../../public/css/print-controls.css?v=1"></head><body class="ns-print-preview"><div class="toolbar"><a href="purchase_requests.php">Back</a><button onclick="print()">Print / Save PDF</button></div><main class="sheet"><div class="title">PURCHASE REQUEST</div><div class="entity"><span>Entity Name: Joni Villanueva General Hospital</span><span>Fund Cluster: <?=e($r['fund_cluster']??'')?></span></div><table class="meta"><tr><td><strong>Office/Section:</strong><br><?=e($r['department_name']??'CSSR')?></td><td><strong>PR No.:</strong> <?=e($r['pr_no'])?><br><strong>Responsibility Center Code:</strong> <?=e($r['responsibility_center']??'')?></td><td><strong>Date:</strong> <?=e($r['request_date'])?></td></tr></table><table class="items"><thead><tr><th style="width:10%">Stock / Property No.</th><th style="width:9%">Unit</th><th>Item Description</th><th style="width:10%">Quantity</th><th style="width:13%">Unit Cost</th><th style="width:14%">Total Cost</th></tr></thead><tbody><?php $total=0;foreach($items as$i):$line=(float)$i['quantity_requested']*(float)$i['unit_cost'];$total+=$line;?><tr><td></td><td class="center"><?=e($i['unit']??'')?></td><td><?=e($i['item_description'])?></td><td class="center"><?=$i['quantity_requested']?></td><td class="num"><?=number_format((float)$i['unit_cost'],2)?></td><td class="num"><?=number_format($line,2)?></td></tr><?php endforeach;?><?php for($x=count($items);$x<12;$x++):?><tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr><?php endfor;?><tr><td colspan="5" class="num"><strong>SUBTOTAL:</strong></td><td class="num"><strong><?=number_format($total,2)?></strong></td></tr></tbody></table><div class="purpose"><strong>Charged to:</strong> <?=e($r['charged_to']??'')?><br><br><strong>Purpose:</strong> <?=e($r['purpose']??'')?></div><div class="sign"><div>Requested by:<strong><?=e($r['requested_by'])?></strong><small>Printed Name and Signature</small></div><div>Approved by:<strong><?=e($r['approved_by']??'')?></strong><small>Printed Name and Signature</small></div></div></main></body></html>
